mapper.sql:
from rm_user_t u where u.deleted = 0 and exists ( select 1 from rm_user_tenant_rela_t utr where utr.user_id = u.id and utr.tenant_id = #{tenantId} and utr.status = 1 and utr.is_del = 0 )
and u.user_name like concat('%', #{userName}, '%')
and u.real_name like concat('%', #{realName}, '%')
and u.id in
#{id}

mapper.select:
select u.*

 order by u.create_time, u.id
 limit #{limit} offset #{offset}
